questions.solution:
function parsePage(text) {
  if (!/^\d+$/.test(text)) return 1;
  const page = Number(text);
  if (page < 1) return 1;
  return page;
}

console.log(parsePage("3"), parsePage(""), parsePage("0"), parsePage("2.5"), parsePage("abc"), parsePage(" 4"));

