function sumKobo(texts) {
  let total = 0;
  for (const text of texts) {
    total = total + text;
  }
  return total;
}

console.log(sumKobo(["1500", "250", "4000"]), sumKobo(["100", "12.5"]), sumKobo(["100", "abc"]), sumKobo([]));

questions.solution:
function sumKobo(texts) {
  let total = 0;
  for (const text of texts) {
    const amount = Number(text);
    if (!Number.isInteger(amount)) return null;
    total = total + amount;
  }
  return total;
}

console.log(sumKobo(["1500", "250", "4000"]), sumKobo(["100", "12.5"]), sumKobo(["100", "abc"]), sumKobo([]));

