questions.solution:
function kindOf(value) {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  if (value instanceof Date) return "date";
  return typeof value;
}

console.log(kindOf(null), kindOf([]), kindOf(new Date(0)), kindOf({}), kindOf("x"), kindOf(5n), kindOf(() => 1));

