questions.solution:
function sortedPrices(texts) {
  const numbers = [];
  for (const text of texts) numbers.push(Number(text));
  return numbers.toSorted((a, b) => a - b);
}

const raw = ["1500", "200", "85", "10000"];
console.log(sortedPrices(raw), raw);

